query getScores($scoreLevel: ScoreLevel!, $filter: Filter) {
  scores(scoreLevel: $scoreLevel, filter: $filter) {
    id
    name
    score
    nodeType
    improvement
    timeLost
    uuid
    thresholds {
      experience
      numberOfDevices
    }
    level
    appType
    troubleshootUrl
    devicesInvestigationUrl
    usersInvestigationUrl
  }
}
